using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based metadata
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented = true
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine(json);

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
//    Use a resolver that only knows about 'int' to show a negative case.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new IntOnlyResolver())
};

if (limited.TryGetTypeInfo(typeof(int), out JsonTypeInfo? intInfo))
    Console.WriteLine($"\n✔ Metadata available for: {intInfo!.Type.Name}");
else
    Console.WriteLine("\n✘ No metadata for int");

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("✔ Metadata available for Person");
else
    Console.WriteLine("✘ No metadata for Person — resolver doesn't support it");

// --- Supporting types ---------------------------------------------------

record Person(string Name, int Age);

/// <summary>A resolver that only provides metadata for <see cref="int"/>.</summary>
sealed class IntOnlyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) =>
        type == typeof(int) ? JsonMetadataServices.CreateValueInfo<int>(options, JsonMetadataServices.Int32Converter) : null;
}

